import{_ as e,c as t,o as r,b2 as d}from"./chunks/framework.CUhoHPxN.js";const u=JSON.parse('{"title":"C7ViewSwitch（C7 视图切换容器）设计说明","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/specs/2026-05-08-c7-view-switch-design.md","filePath":"superpowers/specs/2026-05-08-c7-view-switch-design.md"}'),n={name:"superpowers/specs/2026-05-08-c7-view-switch-design.md"};function s(c,o,g,a,i,l){return r(),t("div",null,[...o[0]||(o[0]=[d('<h1 id="c7viewswitch-c7-视图切换容器-设计说明" tabindex="-1">C7ViewSwitch（C7 视图切换容器）设计说明 <a class="header-anchor vp-link" href="#c7viewswitch-c7-视图切换容器-设计说明" aria-label="Permalink to &quot;C7ViewSwitch（C7 视图切换容器）设计说明&quot;">​</a></h1><p><strong>日期</strong>：2026-05-08<br><strong>状态</strong>：已定稿（经 brainstorming 澄清与「整稿确认」）<br><strong>依据</strong>：<code>原始需求/前端/C7视图切换容器.md</code> + Q&amp;A 结论（1B、2A、3A、4A、5A、6A）及实现路径 <strong>路径 1</strong>（单文件 <code>index.vue</code>）</p><hr><h2 id="_1-背景与目标" tabindex="-1">1. 背景与目标 <a class="header-anchor vp-link" href="#_1-背景与目标" aria-label="Permalink to &quot;1. 背景与目标&quot;">​</a></h2><ul><li><strong>背景</strong>：部分页面需在多个「视图 / 表单步骤」间切换（如列表 → 新增 → 编辑 → 详情），希望由<strong>单一容器</strong>统一管理切换、返回、标题区与过渡动画。</li><li><strong>目标</strong>：提供基于 <strong><code>v-model</code></strong>（视图名 <code>string</code>）的切换容器：按 <strong><code>views</code></strong> 配置与当前值渲染<strong>具名插槽</strong>；内部维护<strong>历史栈</strong>，提供 <strong><code>goBack</code></strong>；可选 <strong><code>ElPageHeader</code></strong>；过渡可关闭或自定义。</li><li><strong>非目标</strong>：与 <strong><code>vue-router</code></strong> 的深度绑定或自动同步；复杂「浏览器级」前进 / 后退（仅栈式上一视图）。</li></ul><hr><h2 id="_2-命名、边界与落点" tabindex="-1">2. 命名、边界与落点 <a class="header-anchor vp-link" href="#_2-命名、边界与落点" aria-label="Permalink to &quot;2. 命名、边界与落点&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>项</th><th>约定</th></tr></thead><tbody><tr><td><strong>对外组件名</strong></td><td><strong><code>C7ViewSwitch</code></strong>（与 <code>C7Switch</code> 开关区分）</td></tr><tr><td><strong>目录</strong></td><td><code>quick-ui/src/packages/C7ViewSwitch/index.vue</code></td></tr><tr><td><strong>实现形态</strong></td><td><strong>单文件组件</strong>；栈与渲染同处一处。若后续栈逻辑显著膨胀（经验阈值约 <strong>80+ 行</strong>），再抽离 <code>useViewStack</code> 等 composable（<strong>本期不做</strong>）。</td></tr><tr><td><strong>全局注册</strong></td><td>在 <strong><code>quick-ui/src/packages/index.js</code></strong> 中 <strong><code>export</code></strong> 与 <strong><code>installPackages</code></strong> 注册，与其它 C7 一致。</td></tr></tbody></table></div><p><strong>职责</strong>：按配置与 <code>modelValue</code> 渲染对应插槽；维护内部历史栈；暴露 <strong><code>switchTo</code> / <code>goBack</code></strong> 及只读栈快照；可选页头与过渡；未匹配视图时 <strong><code>not-found</code> + <code>#empty</code> 兜底</strong>。</p><p><strong>不负责</strong>：路由跳转、权限；业务表单的校验与提交（由槽内页面自行处理）。</p><hr><h2 id="_3-视图配置与别名" tabindex="-1">3. 视图配置与别名 <a class="header-anchor vp-link" href="#_3-视图配置与别名" aria-label="Permalink to &quot;3. 视图配置与别名&quot;">​</a></h2><ul><li><strong>主配置 <code>views</code></strong>：<code>Array&lt;ViewConfig&gt;</code>，其中 <strong><code>ViewConfig</code></strong> 至少包含： <ul><li><strong><code>name: string</code></strong>：视图标识，与 <code>v-model</code> 比较；具名插槽名为 <strong><code>#&lt;name&gt;</code></strong>。</li><li><strong><code>title?: string</code></strong>：可选；供 <code>ElPageHeader</code> 标题等展示。</li><li><strong><code>closeIndex?: string</code></strong>：可选；<strong><code>goBack</code> 且历史栈为空</strong>时，作为回落目标视图名（须能在 <code>views</code> 中匹配，否则按「无回落」处理并走 <strong><code>back-empty</code></strong>）。</li></ul></li><li><strong>兼容别名 <code>showIndexs</code></strong>：与 <strong><code>views</code> 同结构、同语义</strong>。若二者<strong>同时</strong>传入，以 <strong><code>views</code> 为准</strong>（与原始需求「views 优先」一致）。</li></ul><hr><h2 id="_4-历史栈与-v-model-语义-2a" tabindex="-1">4. 历史栈与 <code>v-model</code> 语义（2A） <a class="header-anchor vp-link" href="#_4-历史栈与-v-model-语义-2a" aria-label="Permalink to &quot;4. 历史栈与 `v-model` 语义（2A）&quot;">​</a></h2><ul><li><strong>栈内元素</strong>：历史 <strong><code>modelValue</code> 字符串</strong>（视图名），栈底为较早、栈顶为较近；<strong>仅</strong>由 <strong><code>switchTo</code></strong>、<strong><code>goBack</code></strong> 修改（push / pop）。</li><li><strong><code>switchTo(targetName)</code></strong><ul><li>若 <strong><code>views</code> 中无 <code>name === targetName</code></strong>： <strong><code>emit(&#39;not-found&#39;, targetName)</code></strong>，<strong>不</strong>更新 <code>modelValue</code>，<strong>不</strong>改栈。</li><li>若 <strong><code>targetName</code> 与当前 <code>modelValue</code> 相同</strong>：<strong>no-op</strong>（不入栈、不 <code>emit(&#39;update:modelValue&#39;)</code>、不 <code>emit(&#39;change&#39;)</code>）。</li><li>否则：将<strong>当前</strong> <code>modelValue</code> <strong>压入栈顶</strong>，再 <strong><code>emit(&#39;update:modelValue&#39;, targetName)</code></strong>，并 <strong><code>emit(&#39;change&#39;, targetName, matchedConfig)</code></strong>（<code>matchedConfig</code> 为匹配到的 <code>ViewConfig</code> 对象引用或等价只读形态，实现计划里写死）。</li></ul></li><li><strong><code>goBack()</code></strong><ul><li>若栈<strong>非空</strong>：弹出栈顶作为上一视图名，<strong><code>emit(&#39;update:modelValue&#39;, previousName)</code></strong>，并 <strong><code>emit(&#39;back&#39;, previousName, previousConfig)</code></strong>（载荷与 <code>change</code> 对齐策略一致）。</li><li>若栈<strong>为空</strong>：依次尝试 <strong>当前</strong>匹配项的 <strong><code>closeIndex</code></strong>、组件 <strong><code>defaultView</code> prop</strong>（<code>string</code>，须为合法视图名）；若存在且与当前不同，则 <strong><code>emit(&#39;update:modelValue&#39;, …)</code></strong> 并 <strong><code>emit(&#39;change&#39;, …)</code></strong>（视为一次导航）。若仍无法回落：<strong><code>emit(&#39;back-empty&#39;)</code></strong>，<strong>不改变</strong> <code>modelValue</code>（3A）。</li><li><strong><code>back-empty</code> 载荷</strong>：<strong>无参数</strong>（保持简单；若业务需要当前上下文，可读 <code>modelValue</code> / <code>ref.currentConfig</code>）。</li></ul></li><li><strong>父组件直接修改绑定（<code>v-model</code> / <code>modelValue</code>）</strong>：仅切换当前展示视图，<strong>不入栈、不出栈</strong>；历史栈<strong>保持不变</strong>（2A）。 <ul><li><strong>说明</strong>：此后栈可能与业务「真实路径」不一致；业务在父级强行改视图时，应自行约定一致性（后续<strong>可选</strong>暴露 <strong><code>clearHistory()</code></strong>，<strong>本期不列入必做</strong>；若实现成本极低可在实现阶段顺带暴露，以代码评审为准）。</li></ul></li></ul><hr><h2 id="_5-生命周期与事件-5a" tabindex="-1">5. 生命周期与事件（5A） <a class="header-anchor vp-link" href="#_5-生命周期与事件-5a" aria-label="Permalink to &quot;5. 生命周期与事件（5A）&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>事件</th><th>触发条件</th></tr></thead><tbody><tr><td><strong><code>update:modelValue</code></strong></td><td>任意导致 <code>modelValue</code> 合法更新的路径。</td></tr><tr><td><strong><code>change(viewName, config)</code></strong></td><td><strong><code>modelValue</code> 变为新值且与旧值不同</strong>时；<strong>不含</strong>首次挂载时的初始同步（5A）。来源含 <strong><code>switchTo</code></strong>、<strong><code>goBack</code></strong>、父级直接改绑定、空栈回落成功等。</td></tr><tr><td><strong><code>back(viewName, config)</code></strong></td><td><strong><code>goBack</code></strong> 且<strong>栈非空</strong>、已成功回到上一视图时（载荷为<strong>回到的那一屏</strong>的视图名与配置，实现计划与 JSDoc 写清）。</td></tr><tr><td><strong><code>not-found(viewName)</code></strong></td><td><strong><code>switchTo</code></strong> 指向未配置视图名。</td></tr><tr><td><strong><code>back-empty</code></strong></td><td><strong><code>goBack</code></strong>（或页头触发等价逻辑）时栈空，且<strong>无</strong>有效 <strong><code>closeIndex</code> / <code>defaultView</code></strong> 回落。</td></tr></tbody></table></div><p><strong>模板监听</strong>：Vue 3 中 <code>emit</code> 在脚本侧使用 camelCase（如 <strong><code>backEmpty</code></strong>）时，模板仍写 <strong><code>@back-empty</code></strong>；设计文档以 <strong>kebab-case</strong> 描述用户侧监听名。</p><hr><h2 id="_6-过渡-4a" tabindex="-1">6. 过渡（4A） <a class="header-anchor vp-link" href="#_6-过渡-4a" aria-label="Permalink to &quot;6. 过渡（4A）&quot;">​</a></h2><ul><li><strong><code>transition</code> prop</strong>：类型 <strong><code>boolean | string</code></strong>。 <ul><li><strong><code>false</code></strong>：不包裹 <strong><code>&lt;Transition&gt;</code></strong>，无过渡。</li><li><strong><code>true</code></strong>：使用组件约定默认 <strong><code>name</code></strong>（如 <strong><code>c7-view-switch</code></strong>，实现时写死常量）。</li><li><strong><code>string</code></strong>：作为 <strong><code>&lt;Transition :name=&quot;transition&quot;&gt;</code></strong> 的 <code>name</code>，供业务自定义 CSS 过渡类名。</li></ul></li></ul><hr><h2 id="_7-插槽" tabindex="-1">7. 插槽 <a class="header-anchor vp-link" href="#_7-插槽" aria-label="Permalink to &quot;7. 插槽&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>插槽</th><th>说明</th></tr></thead><tbody><tr><td><strong><code>#&lt;view.name&gt;</code></strong>（具名，scoped）</td><td>参数：<strong><code>{ config, switchTo, goBack }</code></strong>，与原始需求一致；<code>config</code> 为当前视图 <strong><code>ViewConfig</code></strong>。</td></tr><tr><td><strong><code>#header-content</code></strong></td><td>可选 <code>ElPageHeader</code> 的 <strong>content</strong> 区域（与 EP 插槽名对齐方式在实现计划中对照当前 EP 版本文档）。</td></tr><tr><td><strong><code>#empty</code></strong></td><td><strong><code>modelValue</code> 无法在 <code>views</code> 中匹配</strong>时渲染；<strong>若无此插槽则空白占位</strong>（6A）。</td></tr></tbody></table></div><hr><h2 id="_8-可选-elpageheader" tabindex="-1">8. 可选 <code>ElPageHeader</code> <a class="header-anchor vp-link" href="#_8-可选-elpageheader" aria-label="Permalink to &quot;8. 可选 `ElPageHeader`&quot;">​</a></h2><ul><li><strong><code>showPageHeader</code></strong>：<code>boolean</code>，默认 <strong><code>false</code></strong>。为 <strong><code>true</code></strong> 时渲染 <strong><code>ElPageHeader</code></strong>。</li><li><strong>标题</strong>：优先当前匹配项的 <strong><code>title</code></strong>；若无 <strong><code>title</code></strong>，使用<strong>空字符串或占位文案</strong>二选一（实现计划里选定一种并写入 JSDoc，避免未定义行为）。</li><li><strong>页头「返回」</strong>：触发与 <strong><code>goBack()</code></strong> 相同的逻辑（含空栈回落与 <strong><code>back-empty</code></strong>）。</li></ul><hr><h2 id="_9-其它-props-与暴露" tabindex="-1">9. 其它 Props 与暴露 <a class="header-anchor vp-link" href="#_9-其它-props-与暴露" aria-label="Permalink to &quot;9. 其它 Props 与暴露&quot;">​</a></h2><ul><li><strong><code>defaultView?: string</code></strong>：见第 4 节空栈回落。</li><li><strong><code>defineExpose</code></strong>：<strong><code>switchTo</code></strong>、<strong><code>goBack</code></strong>、<strong><code>currentConfig</code></strong>（当前匹配 <code>ViewConfig</code> 或 <code>null</code>）、<strong><code>viewHistory</code></strong>（栈的<strong>只读快照</strong>，如返回新数组或 <code>readonly</code>，禁止外部直接 <code>mutate</code> 内部栈）。</li></ul><hr><h2 id="_10-错误处理与测试要点" tabindex="-1">10. 错误处理与测试要点 <a class="header-anchor vp-link" href="#_10-错误处理与测试要点" aria-label="Permalink to &quot;10. 错误处理与测试要点&quot;">​</a></h2><ul><li><strong><code>not-found</code></strong>：仅非法 <strong><code>switchTo</code></strong>。</li><li><strong><code>back-empty</code></strong>：空栈且无有效回落。</li><li><strong>建议测试</strong>：栈 push/pop 顺序；<code>switchTo</code> 同目标 no-op；父级改 <code>v-model</code> <strong>不入栈</strong>；首次挂载<strong>无</strong> <code>change</code>；未匹配 + 有/无 <strong><code>#empty</code></strong>；<code>transition</code> 三态；<code>showPageHeader</code> 返回与 <strong><code>goBack</code></strong> 一致。</li></ul><hr><h2 id="_11-文档与集成" tabindex="-1">11. 文档与集成 <a class="header-anchor vp-link" href="#_11-文档与集成" aria-label="Permalink to &quot;11. 文档与集成&quot;">​</a></h2><ul><li><strong>VitePress</strong>：在 <code>docs/</code> 侧增加与其它 C7 一致的组件说明页（路径随现有文档结构），含基础示例与「父级直接改 <code>v-model</code> 与栈」的说明（<strong>本期纳入实现计划任务项</strong>）。</li></ul><hr><h2 id="_12-与原始需求-c7switchform-对照" tabindex="-1">12. 与原始需求（C7SwitchForm）对照 <a class="header-anchor vp-link" href="#_12-与原始需求-c7switchform-对照" aria-label="Permalink to &quot;12. 与原始需求（C7SwitchForm）对照&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>原始项</th><th>定稿</th></tr></thead><tbody><tr><td>组件名 C7SwitchForm</td><td><strong>C7ViewSwitch</strong>（避免与 <code>C7Switch</code> 混淆）</td></tr><tr><td><code>views</code> / <code>showIndexs</code></td><td><strong>保留</strong>，优先级 <strong><code>views</code></strong></td></tr><tr><td>事件 / 插槽 / 暴露能力</td><td><strong>对齐</strong>；新增明确语义：<strong><code>back-empty</code></strong>、<strong><code>switchTo</code> 同值 no-op</strong>、<strong>首次不 <code>change</code></strong></td></tr></tbody></table></div>',41)])])}const m=e(n,[["render",s]]);export{u as __pageData,m as default};
